mapper.select:
SELECT COUNT(*)
FROM t_refund_order ro
INNER JOIN t_pay_order po ON po.pay_order_id = ro.pay_order_id
WHERE po.account_id = #{accountId}
  AND ro.created_at >= #{startTime}
  AND ro.created_at < #{endTime}
  AND ro.state = 2

SELECT COUNT(*)
FROM t_chargeback_record
WHERE account_id = #{accountId}
  AND created_at >= #{startTime}
  AND created_at < #{endTime}

SELECT COUNT(*)
FROM t_chargeback_record
WHERE account_id = #{accountId}
  AND created_at >= #{startTime}
  AND created_at < #{endTime}
  AND chargeback_type IN ('fraudulent', 'unrecognized', 'duplicate', 'product_not_received')
